import{z as t,x as o,o as e,c as n,q as s,j as A,D as E,d as r,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"系统安全案例与收束","description":"","frontmatter":{"title":"系统安全案例与收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ss-case-map.md","filePath":"cs/ss-case-map.md","lastUpdated":1791413859000}'),d={name:"cs/ss-case-map.md"};function p(c,a,h,C,D,m){const B=o("Mermaid");return e(),n("div",null,[a[2]||(a[2]=s('<h1 id="系统安全案例与收束" tabindex="-1">系统安全案例与收束 <a class="header-anchor" href="#系统安全案例与收束" aria-label="Permalink to &quot;系统安全案例与收束&quot;">​</a></h1><div class="epigraph"><p>案例不是故事集，是给前面八课做的交叉验证：每一课钉下的类别，都得在真实事故里出现过至少一次，这门课才自洽。</p><footer>—— 据 Dirty Pipe（Kellermann, 2022）、Log4Shell（Apache/CISA, 2021）、CrowdStrike 事件初步报告（2024）公开材料整理</footer></div><p><a href="/cs/ss-cloud-model">上一课</a>把模型收在身份与责任分割，身份成了剩下的那道墙。本课程到此收束：不再引入新机制，用四个横跨多课的案例做交叉验证——每个案例至少落在两课的类别上——最后给出全课程的地图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单课视角各管一段，真实事故却是组合的：一个内核 bug 走供应链通道进来，被云上的身份放大成全球事件。只学类别表而不看组合，会低估两种风险：机制正确但路径意外的攻击，与机制普通但规模放大的事故。案例的挑选标准因此有两条：至少落在两课的交点上，且公开材料足以钉住事实。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="四个案例对表" tabindex="-1">四个案例对表 <a class="header-anchor" href="#四个案例对表" aria-label="Permalink to &quot;四个案例对表&quot;">​</a></h3><p>Dirty Pipe（CVE-2022-0847，2022 年 3 月）：Linux 管道缓冲复用时标志位未清零，攻击者可向任意只读文件追加写，直达提权——<a href="/cs/ss-kernel-vuln-classes">内核类别</a>里未初始化与逻辑类的合体，修复走补丁窗口。Log4Shell（CVE-2021-44228，2021 年 12 月）：一个日志库的配置表达式可触发远程类加载，把互不相干的软件折成同一批受害者——<a href="/cs/ss-supply-chain">供应链</a>生态站的教科书案，SBOM 的价值是回答「我在不在其中」。CrowdStrike 停摆（2024 年 7 月 19 日）：一份内容更新经内核态驱动解析出空指针，全球约 850 万台 Windows 崩溃（Microsoft 口径）——「不可信输入抵达特权计算」的合法输入版，叠加更新管道与「可用性也是安全」两课的论点。Pegasus 零点击：消息解析器当入口，链式走到提权——<a href="/cs/ss-mobile">移动栈</a>的格子被绕过入口攻入，落点在<a href="/cs/ss-hardware-perspective">硬件面</a>与取证。</p><p><span class="marginnote">四个案例里只有一个用了「漏洞」的狭义定义：CrowdStrike 案的输入完全合法，坏的是特权层对它的健壮性；事故不是攻破，是设计把可用性押在了内核驱动的解析器上。</span></p><p><span class="marginnote">数字实例：CrowdStrike 一次内容更新让约 850 万台 Windows 同时蓝屏——单个句柄没做健壮性检查，结果被「同一更新管道推送全部终端」这个规模杠杆放大成全球停摆；这就是「机制普通但规模放大」的典型。</span></p>',10)),(e(),A(i,null,{default:E(()=>[l(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20A1%5B%22Dirty%20Pipe%EF%BC%9A%E5%86%85%E6%A0%B8%E7%B1%BB%E5%88%AB%20%2B%20%E8%A1%A5%E4%B8%81%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20MAP%0A%20%20A2%5B%22Log4Shell%EF%BC%9A%E4%BE%9B%E5%BA%94%E9%93%BE%E7%94%9F%E6%80%81%20%2B%20SBOM%22%5D%20--%3E%20MAP%0A%20%20A3%5B%22CrowdStrike%EF%BC%9A%E6%9B%B4%E6%96%B0%E7%AE%A1%E9%81%93%20%2B%20%E7%89%B9%E6%9D%83%E5%81%A5%E5%A3%AE%E6%80%A7%22%5D%20--%3E%20MAP%0A%20%20A4%5B%22Pegasus%EF%BC%9A%E7%A7%BB%E5%8A%A8%E5%85%A5%E5%8F%A3%20%2B%20%E7%A1%AC%E4%BB%B6%E9%9D%A2%22%5D%20--%3E%20MAP%0A%20%20MAP%5B%22%E5%85%A8%E8%AF%BE%E7%A8%8B%E5%9C%B0%E5%9B%BE%22%5D%20--%3E%20OFF%5B%22%E6%94%BB%E9%98%B2%EF%BC%9A%E7%B1%BB%E5%88%AB%20%2F%20%E6%B2%99%E7%AE%B1%20%2F%20%E4%BE%9B%E5%BA%94%E9%93%BE%20%2F%20fuzzing%22%5D%0A%20%20MAP%20--%3E%20SYS%5B%22%E4%BD%93%E7%B3%BB%EF%BC%9A%E8%AF%AD%E8%A8%80%20%2F%20%E7%A1%AC%E4%BB%B6%20%2F%20%E7%A7%BB%E5%8A%A8%20%2F%20%E4%BA%91%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>地图把两个单元缝起来。攻防单元是一条发现与限制链：<a href="/cs/ss-kernel-vuln-classes">类别表</a>钉敌情，<a href="/cs/ss-sandbox-escape">沙箱</a>限爆炸半径，<a href="/cs/ss-supply-chain">供应链</a>管代码从哪来，<a href="/cs/ss-fuzzing-deep">模糊测试</a>自动找；体系单元是一条构建链：<a href="/cs/ss-memory-safe-langs">语言</a>把内存类证掉，<a href="/cs/ss-hardware-perspective">硬件</a>给根信任并暴露新面，<a href="/cs/ss-mobile">移动</a>是平台标本，<a href="/cs/ss-cloud-model">云</a>把边界换成身份。两链相交于一句话：安全是整条栈的性质——每一层把上一层的假设变成可检查的合同，检查不过的地方就是下一课该写的缺陷。类别表不因新事件过时，因为框架本来就是按「怎么修」而不是按「谁中了招」组织的。</p>',2)),(e(),A(i,null,{default:E(()=>[l(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20CHAIN_A%5B%22%E6%94%BB%E9%98%B2%E9%93%BE%3A%20%E5%8F%91%E7%8E%B0%E4%B8%8E%E9%99%90%E5%88%B6%22%5D%0A%20%20%20%20D1%5B%22%E7%B1%BB%E5%88%AB%E8%A1%A8%3A%20%E6%95%8C%E6%83%85%22%5D%20--%3E%20D2%5B%22fuzzing%3A%20%E8%87%AA%E5%8A%A8%E6%89%BE%22%5D%0A%20%20%20%20D2%20--%3E%20D3%5B%22%E6%B2%99%E7%AE%B1%3A%20%E9%99%90%E7%88%86%E7%82%B8%E5%8D%8A%E5%BE%84%22%5D%0A%20%20%20%20D3%20--%3E%20D4%5B%22%E4%BE%9B%E5%BA%94%E9%93%BE%3A%20%E4%BB%A3%E7%A0%81%E4%BB%8E%E5%93%AA%E6%9D%A5%22%5D%0A%20%20end%0A%20%20subgraph%20CHAIN_B%5B%22%E4%BD%93%E7%B3%BB%E9%93%BE%3A%20%E6%9E%84%E5%BB%BA%22%5D%0A%20%20%20%20C1%5B%22%E8%AF%AD%E8%A8%80%3A%20%E8%AF%81%E6%8E%89%E5%86%85%E5%AD%98%E7%B1%BB%22%5D%20--%3E%20C2%5B%22%E7%A1%AC%E4%BB%B6%3A%20%E6%A0%B9%E4%BF%A1%E4%BB%BB%22%5D%0A%20%20%20%20C2%20--%3E%20C3%5B%22%E7%A7%BB%E5%8A%A8%3A%20%E5%B9%B3%E5%8F%B0%E6%A0%87%E6%9C%AC%22%5D%0A%20%20%20%20C3%20--%3E%20C4%5B%22%E4%BA%91%3A%20%E8%BE%B9%E7%95%8C%E6%8D%A2%E8%BA%AB%E4%BB%BD%22%5D%0A%20%20end%0A%20%20D3%20%3C--%3E%7C%22%E5%90%8C%E4%B8%80%E5%B1%82%E5%90%88%E5%90%8C%E4%BA%92%E7%9B%B8%E6%A3%80%E6%9F%A5%22%7C%20C2%0A%20%20D4%20%3C--%3E%7C%22%E5%90%8C%E4%B8%80%E5%B1%82%E5%90%88%E5%90%8C%E4%BA%92%E7%9B%B8%E6%A3%80%E6%9F%A5%22%7C%20C1%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p><span class="marginnote">直觉类比：案例是这门课的「历年真题」。类别表是课本上的公式，案例是把这些公式各考两遍——一道题同时考两个知识点，你才知道公式不是各自孤立的。</span></p><p><span class="marginnote">常见误区：初学者容易以为新出一次大漏洞，之前学的框架就过时了。本课的立场相反：类别表按「怎么修」组织，Dirty Pipe 不过是「未初始化 + 逻辑类」的一次新实例——变的是受害者名单，不是类别本身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>案例只使用公开材料，不构成利用教学；每案的技术细节以原始报告为准，本课只取与类别表的对应。新事故不会推翻框架——推翻框架的写法是「类别有了新成员」，那是新课文的工作，不是收束课的工作。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>案例的挑选标准：落在两课交点上，公开材料足以钉住事实。</li><li>四案对表：Dirty Pipe 对内核类别，Log4Shell 对供应链，CrowdStrike 对特权健壮性与可用性，Pegasus 对移动与硬件。</li><li>合法输入也能击穿特权层：健壮性与可用性是安全的一部分，不只是防「攻破」。</li><li>攻防单元是发现与限制链，体系单元是构建链；安全是整条栈的性质。</li><li>本课程到此收束：类别表与「每层一层合同」的地图是留下的框架，新事故归新课。</li><li>出处：Kellermann, 2022；Apache 与 CISA 的 Log4Shell 公告；CrowdStrike 初步报告与 Microsoft 估计（2024）；Amnesty International 的 Pegasus 取证报告。</li></ul>',6))])}const _=t(d,[["render",p]]);export{f as __pageData,_ as default};
